def read_csv(p):
    with open(p,encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def write_csv(name, fields, rows):
    p=OUT/name; p.parent.mkdir(parents=True,exist_ok=True)
    with open(p,'w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(rows)
def write_text(name,text):
    p=OUT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def write_json(name,obj): write_text(name,json.dumps(obj,indent=2,ensure_ascii=False,default=str)+'\n')
def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        while True:
            block=f.read(1024*1024)
            if not block: break
            h.update(block)
    return h.hexdigest()
def rel(p): return str(Path(p).relative_to(ROOT)).replace('\\','/')

